pub type Score = { player: Str; points: Int; }

impl PartialEq for Score {
  fn eq(self: &Score, other: &Score) -> Bool {
    return self.points == other.points;
  }
}
impl Eq for Score {}

impl Ord for Score {
  fn cmp(self: &Score, other: &Score) -> Ordering {
    return self.points.cmp(&other.points);
  }
}

fn main() -> Int {
  let mut v = Vec[Score]();
  v.push(Score{ player: "A", points: 100 });
  v.push(Score{ player: "B", points: 250 });
  v.push(Score{ player: "C", points: 150 });
  v.sort();
  return v[v.len() - 1].points;
}
